// Experimental line-by-line YAML validator
// Tests whether a state machine approach can detect common YAML syntax errors

interface ValidationError {
  line: number;
  column: number;
  message: string;
}

interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

export function validateYAML(content: string): ValidationResult {
  const lines = content.split('\n');
  const errors: ValidationError[] = [];
  let indentStack: number[] = [0];
  let inQuote: string | null = null;
  let quoteStartLine = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNum = i + 1;

    // Skip empty lines and comments (simple detection)
    const trimmed = line.trim();
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue;
    }

    // Check for tabs
    if (line.includes('\t')) {
      errors.push({
        line: lineNum,
        column: line.indexOf('\t') + 1,
        message: 'Tab characters are not allowed in YAML'
      });
      continue;
    }

    // Track indentation
    const indent = line.length - line.trimStart().length;

    // Quote tracking (simplified - only handles line-level quotes)
    for (let col = 0; col < line.length; col++) {
      const char = line[col];

      if ((char === '"' || char === "'") && (col === 0 || line[col - 1] !== '\\')) {
        if (inQuote === null) {
          inQuote = char;
          quoteStartLine = lineNum;
        } else if (char === inQuote) {
          inQuote = null;
        }
      }
    }

    // Check for malformed key-value pairs
    if (trimmed.includes(':')) {
      const colonIndex = trimmed.indexOf(':');
      const beforeColon = trimmed.substring(0, colonIndex).trim();

      // Key cannot be empty
      if (beforeColon === '') {
        errors.push({
          line: lineNum,
          column: indent + colonIndex + 1,
          message: 'Empty key before colon'
        });
      }

      // Check for invalid key characters (simplified)
      if (beforeColon.match(/^[0-9]/)) {
        // Numeric keys should be quoted in strict YAML
        // This is a simplification - not all numeric keys are invalid
      }
    }

    // Check indentation consistency
    if (indent > 0) {
      // Check if indent matches any level in stack
      const validIndent = indentStack.some(level => indent === level) ||
                         indent > indentStack[indentStack.length - 1];

      if (indent > indentStack[indentStack.length - 1]) {
        indentStack.push(indent);
      } else if (indent < indentStack[indentStack.length - 1]) {
        // Pop until we find matching or smaller indent
        while (indentStack.length > 1 && indentStack[indentStack.length - 1] > indent) {
          indentStack.pop();
        }

        // Check if we found a matching indent
        if (indentStack[indentStack.length - 1] !== indent) {
          errors.push({
            line: lineNum,
            column: indent + 1,
            message: `Inconsistent indentation (expected ${indentStack[indentStack.length - 1]} spaces, got ${indent})`
          });
        }
      }
    }
  }

  // Check for unclosed quotes
  if (inQuote !== null) {
    errors.push({
      line: quoteStartLine,
      column: 1,
      message: `Unclosed quote (${inQuote})`
    });
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

import { validateYAML } from './validator';

// Test cases for common YAML patterns and errors

const testCases = [
  // Valid YAML cases
  {
    name: 'Valid GitHub Actions workflow',
    yaml: `name: CI
on: [push, pull_request]
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v2
      - name: Run tests
        run: npm test`,
    expectedValid: true
  },
  {
    name: 'Valid Docker Compose',
    yaml: `version: '3.8'
services:
  web:
    image: nginx:latest
    ports:
      - "80:80"
    environment:
      - NODE_ENV=production`,
    expectedValid: true
  },
  {
    name: 'Valid Kubernetes config',
    yaml: `apiVersion: v1
kind: Pod
metadata:
  name: myapp
spec:
  containers:
  - name: myapp
    image: myapp:1.0`,
    expectedValid: true
  },
  {
    name: 'Valid empty file',
    yaml: '',
    expectedValid: true
  },
  {
    name: 'Valid comments only',
    yaml: `# This is a comment
# Another comment`,
    expectedValid: true
  },

  // Invalid YAML cases - should be detected
  {
    name: 'Tab character error',
    yaml: `name: test
\tvalue: invalid`,
    expectedValid: false,
    expectedError: 'Tab characters'
  },
  {
    name: 'Unclosed double quote',
    yaml: `name: "unclosed quote
value: test`,
    expectedValid: false,
    expectedError: 'Unclosed quote'
  },
  {
    name: 'Unclosed single quote',
    yaml: `name: 'unclosed quote
value: test`,
    expectedValid: false,
    expectedError: 'Unclosed quote'
  },
  {
    name: 'Empty key',
    yaml: `: no key here
value: test`,
    expectedValid: false,
    expectedError: 'Empty key'
  },
  {
    name: 'Inconsistent indentation',
    yaml: `parent:
  child1: value
   child2: value`,
    expectedValid: false,
    expectedError: 'Inconsistent indentation'
  },

  // Complex YAML features - may not be validated
  {
    name: 'YAML anchor (advanced feature)',
    yaml: `defaults: &defaults
  adapter: postgres
  host: localhost

development:
  <<: *defaults
  database: dev_db`,
    expectedValid: true, // Our validator won't validate anchors, so it should pass
    note: 'Anchor validation not implemented'
  },
  {
    name: 'Multi-line string with pipe',
    yaml: `description: |
  This is a multi-line
  string value
  with multiple lines`,
    expectedValid: true,
    note: 'Multi-line strings should be accepted'
  },
  {
    name: 'Multi-line string with greater-than',
    yaml: `description: >
  This is a folded
  multi-line string`,
    expectedValid: true,
    note: 'Folded strings should be accepted'
  }
];

// Run tests
console.log('Running YAML validation tests...\n');

let totalTests = 0;
let passedTests = 0;
let detectedErrors = 0;
let missedErrors = 0;
let falsePositives = 0;

testCases.forEach((tc, index) => {
  totalTests++;
  const result = validateYAML(tc.yaml);

  const passed = result.valid === tc.expectedValid;
  if (passed) {
    passedTests++;
    console.log(`✓ Test ${index + 1}: ${tc.name}`);
  } else {
    console.log(`✗ Test ${index + 1}: ${tc.name}`);
    console.log(`  Expected: ${tc.expectedValid ? 'valid' : 'invalid'}`);
    console.log(`  Got: ${result.valid ? 'valid' : 'invalid'}`);

    if (!tc.expectedValid && result.valid) {
      missedErrors++;
      console.log(`  MISSED ERROR: Should have detected ${tc.expectedError || 'syntax error'}`);
    } else if (tc.expectedValid && !result.valid) {
      falsePositives++;
      console.log(`  FALSE POSITIVE: Incorrectly flagged as invalid`);
    }

    if (result.errors.length > 0) {
      console.log(`  Errors found:`);
      result.errors.forEach(err => {
        console.log(`    Line ${err.line}, Col ${err.column}: ${err.message}`);
      });
    }
  }
  if (tc.note) {
    console.log(`  Note: ${tc.note}`);
  }
  console.log('');
});

// Calculate metrics
const intentionalErrors = testCases.filter(tc => !tc.expectedValid).length;
const errorsDetected = intentionalErrors - missedErrors;
const detectionRate = intentionalErrors > 0 ? (errorsDetected / intentionalErrors) * 100 : 0;
const falsePositiveRate = totalTests > 0 ? (falsePositives / totalTests) * 100 : 0;

console.log('=== Results ===');
console.log(`Total tests: ${totalTests}`);
console.log(`Passed: ${passedTests}/${totalTests} (${((passedTests/totalTests)*100).toFixed(1)}%)`);
console.log('');
console.log('=== Error Detection Metrics ===');
console.log(`Intentional errors: ${intentionalErrors}`);
console.log(`Errors detected: ${errorsDetected}`);
console.log(`Errors missed: ${missedErrors}`);
console.log(`Detection rate: ${detectionRate.toFixed(1)}%`);
console.log('');
console.log(`False positives: ${falsePositives}`);
console.log(`False positive rate: ${falsePositiveRate.toFixed(1)}%`);
console.log('');

// Hypothesis validation
console.log('=== Hypothesis Validation ===');
console.log('HYP-002 Criteria:');
console.log('- Detection rate >= 80%: ' + (detectionRate >= 80 ? '✓ PASS' : '✗ FAIL'));
console.log('- False positive rate < 5%: ' + (falsePositiveRate < 5 ? '✓ PASS' : '✗ FAIL'));
console.log('');

if (detectionRate >= 80 && falsePositiveRate < 5) {
  console.log('✓ HYP-002 CONFIRMED: Line-by-line parser meets validation criteria');
} else {
  console.log('✗ HYP-002 REJECTED: Line-by-line parser does not meet validation criteria');
}

import { validateYAML } from './validator';

// Additional edge case testing for real-world scenarios

const edgeCases = [
  {
    name: 'Real GitHub Actions with complex nesting',
    yaml: `name: Test
on:
  push:
    branches:
      - main
      - develop
  pull_request:
jobs:
  build:
    runs-on: ubuntu-latest
    strategy:
      matrix:
        node-version: [14, 16, 18]
    steps:
      - uses: actions/checkout@v3
      - name: Setup Node
        uses: actions/setup-node@v3
        with:
          node-version: \${{ matrix.node-version }}`,
    shouldPass: true
  },
  {
    name: 'Malformed GitHub Actions (broken indentation)',
    yaml: `name: Test
jobs:
  build:
    runs-on: ubuntu-latest
     steps:
      - uses: actions/checkout@v3`,
    shouldPass: false
  },
  {
    name: 'Docker Compose with environment variables',
    yaml: `version: '3.8'
services:
  db:
    image: postgres:13
    environment:
      POSTGRES_PASSWORD: example
      POSTGRES_USER: admin
    volumes:
      - db-data:/var/lib/postgresql/data
volumes:
  db-data:`,
    shouldPass: true
  },
  {
    name: 'Kubernetes with multi-line command',
    yaml: `apiVersion: batch/v1
kind: Job
metadata:
  name: backup
spec:
  template:
    spec:
      containers:
      - name: backup
        image: postgres:13
        command:
          - /bin/sh
          - -c
          - |
            echo "Starting backup"
            pg_dump database > backup.sql`,
    shouldPass: true
  },
  {
    name: 'Mixed quote types',
    yaml: `mixed: "double quotes"
single: 'single quotes'
unquoted: no quotes`,
    shouldPass: true
  },
  {
    name: 'Nested lists and objects',
    yaml: `users:
  - name: Alice
    roles:
      - admin
      - developer
  - name: Bob
    roles:
      - viewer`,
    shouldPass: true
  },
  {
    name: 'Boolean and null values',
    yaml: `enabled: true
disabled: false
nothing: null
tilde: ~`,
    shouldPass: true
  }
];

console.log('Running edge case validation tests...\n');

let passed = 0;
let failed = 0;

edgeCases.forEach((tc, index) => {
  const result = validateYAML(tc.yaml);
  const success = (result.valid === tc.shouldPass);

  if (success) {
    passed++;
    console.log(`✓ Edge case ${index + 1}: ${tc.name}`);
  } else {
    failed++;
    console.log(`✗ Edge case ${index + 1}: ${tc.name}`);
    console.log(`  Expected: ${tc.shouldPass ? 'valid' : 'invalid'}`);
    console.log(`  Got: ${result.valid ? 'valid' : 'invalid'}`);

    if (result.errors.length > 0) {
      console.log(`  Errors:`);
      result.errors.forEach(err => {
        console.log(`    Line ${err.line}, Col ${err.column}: ${err.message}`);
      });
    }
  }
  console.log('');
});

console.log('=== Edge Case Results ===');
console.log(`Total: ${edgeCases.length}`);
console.log(`Passed: ${passed}`);
console.log(`Failed: ${failed}`);
console.log(`Success rate: ${((passed/edgeCases.length)*100).toFixed(1)}%`);

