// Experimental line-by-line YAML validator
// Tests whether a state machine approach can detect common YAML syntax errors

interface ValidationError {
  line: number;
  column: number;
  message: string;
}

interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

export function validateYAML(content: string): ValidationResult {
  const lines = content.split('\n');
  const errors: ValidationError[] = [];
  let indentStack: number[] = [0];
  let inQuote: string | null = null;
  let quoteStartLine = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNum = i + 1;

    // Skip empty lines and comments (simple detection)
    const trimmed = line.trim();
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue;
    }

    // Check for tabs
    if (line.includes('\t')) {
      errors.push({
        line: lineNum,
        column: line.indexOf('\t') + 1,
        message: 'Tab characters are not allowed in YAML'
      });
      continue;
    }

    // Track indentation
    const indent = line.length - line.trimStart().length;

    // Quote tracking (simplified - only handles line-level quotes)
    for (let col = 0; col < line.length; col++) {
      const char = line[col];

      if ((char === '"' || char === "'") && (col === 0 || line[col - 1] !== '\\')) {
        if (inQuote === null) {
          inQuote = char;
          quoteStartLine = lineNum;
        } else if (char === inQuote) {
          inQuote = null;
        }
      }
    }

    // Check for malformed key-value pairs
    if (trimmed.includes(':')) {
      const colonIndex = trimmed.indexOf(':');
      const beforeColon = trimmed.substring(0, colonIndex).trim();

      // Key cannot be empty
      if (beforeColon === '') {
        errors.push({
          line: lineNum,
          column: indent + colonIndex + 1,
          message: 'Empty key before colon'
        });
      }

      // Check for invalid key characters (simplified)
      if (beforeColon.match(/^[0-9]/)) {
        // Numeric keys should be quoted in strict YAML
        // This is a simplification - not all numeric keys are invalid
      }
    }

    // Check indentation consistency
    if (indent > 0) {
      // Check if indent matches any level in stack
      const validIndent = indentStack.some(level => indent === level) ||
                         indent > indentStack[indentStack.length - 1];

      if (indent > indentStack[indentStack.length - 1]) {
        indentStack.push(indent);
      } else if (indent < indentStack[indentStack.length - 1]) {
        // Pop until we find matching or smaller indent
        while (indentStack.length > 1 && indentStack[indentStack.length - 1] > indent) {
          indentStack.pop();
        }

        // Check if we found a matching indent
        if (indentStack[indentStack.length - 1] !== indent) {
          errors.push({
            line: lineNum,
            column: indent + 1,
            message: `Inconsistent indentation (expected ${indentStack[indentStack.length - 1]} spaces, got ${indent})`
          });
        }
      }
    }
  }

  // Check for unclosed quotes
  if (inQuote !== null) {
    errors.push({
      line: quoteStartLine,
      column: 1,
      message: `Unclosed quote (${inQuote})`
    });
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

import { validateYAML } from './validator';

// Test cases for common YAML patterns and errors

const testCases = [
  // Valid YAML cases
  {
    name: 'Valid GitHub Actions workflow',
    yaml: `name: CI
on: [push, pull_request]
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v2
      - name: Run tests
        run: npm test`,
    expectedValid: true
  },
  {
    name: 'Valid Docker Compose',
    yaml: `version: '3.8'
services:
  web:
    image: nginx:latest
    ports:
      - "80:80"
    environment:
      - NODE_ENV=production`,
    expectedValid: true
  },
  {
    name: 'Valid Kubernetes config',
    yaml: `apiVersion: v1
kind: Pod
metadata:
  name: myapp
spec:
  containers:
  - name: myapp
    image: myapp:1.0`,
    expectedValid: true
  },
  {
    name: 'Valid empty file',
    yaml: '',
    expectedValid: true
  },
  {
    name: 'Valid comments only',
    yaml: `# This is a comment
# Another comment`,
    expectedValid: true
  },

  // Invalid YAML cases - should be detected
  {
    name: 'Tab character error',
    yaml: `name: test
\tvalue: invalid`,
    expectedValid: false,
    expectedError: 'Tab characters'
  },
  {
    name: 'Unclosed double quote',
    yaml: `name: "unclosed quote
value: test`,
    expectedValid: false,
    expectedError: 'Unclosed quote'
  },
  {
    name: 'Unclosed single quote',
    yaml: `name: 'unclosed quote
value: test`,
    expectedValid: false,
    expectedError: 'Unclosed quote'
  },
  {
    name: 'Empty key',
    yaml: `: no key here
value: test`,
    expectedValid: false,
    expectedError: 'Empty key'
  },
  {
    name: 'Inconsistent indentation',
    yaml: `parent:
  child1: value
   child2: value`,
    expectedValid: false,
    expectedError: 'Inconsistent indentation'
