  // Complex YAML features - may not be validated
  {
    name: 'YAML anchor (advanced feature)',
    yaml: `defaults: &defaults
  adapter: postgres
  host: localhost

development:
  <<: *defaults
  database: dev_db`,
    expectedValid: true, // Our validator won't validate anchors, so it should pass
    note: 'Anchor validation not implemented'
  },
  {
    name: 'Multi-line string with pipe',
    yaml: `description: |
  This is a multi-line
  string value
  with multiple lines`,
    expectedValid: true,
    note: 'Multi-line strings should be accepted'
  },
  {
    name: 'Multi-line string with greater-than',
    yaml: `description: >
  This is a folded
  multi-line string`,
    expectedValid: true,
    note: 'Folded strings should be accepted'
  }
];

// Run tests
console.log('Running YAML validation tests...\n');

let totalTests = 0;
let passedTests = 0;
let detectedErrors = 0;
let missedErrors = 0;
let falsePositives = 0;

testCases.forEach((tc, index) => {
  totalTests++;
  const result = validateYAML(tc.yaml);

  const passed = result.valid === tc.expectedValid;
  if (passed) {
    passedTests++;
    console.log(`✓ Test ${index + 1}: ${tc.name}`);
  } else {
    console.log(`✗ Test ${index + 1}: ${tc.name}`);
    console.log(`  Expected: ${tc.expectedValid ? 'valid' : 'invalid'}`);
    console.log(`  Got: ${result.valid ? 'valid' : 'invalid'}`);

    if (!tc.expectedValid && result.valid) {
      missedErrors++;
      console.log(`  MISSED ERROR: Should have detected ${tc.expectedError || 'syntax error'}`);
    } else if (tc.expectedValid && !result.valid) {
      falsePositives++;
      console.log(`  FALSE POSITIVE: Incorrectly flagged as invalid`);
    }

    if (result.errors.length > 0) {
      console.log(`  Errors found:`);
      result.errors.forEach(err => {
        console.log(`    Line ${err.line}, Col ${err.column}: ${err.message}`);
      });
    }
  }
  if (tc.note) {
    console.log(`  Note: ${tc.note}`);
  }
  console.log('');
});

// Calculate metrics
const intentionalErrors = testCases.filter(tc => !tc.expectedValid).length;
const errorsDetected = intentionalErrors - missedErrors;
const detectionRate = intentionalErrors > 0 ? (errorsDetected / intentionalErrors) * 100 : 0;
const falsePositiveRate = totalTests > 0 ? (falsePositives / totalTests) * 100 : 0;

console.log('=== Results ===');
console.log(`Total tests: ${totalTests}`);
console.log(`Passed: ${passedTests}/${totalTests} (${((passedTests/totalTests)*100).toFixed(1)}%)`);
console.log('');
console.log('=== Error Detection Metrics ===');
console.log(`Intentional errors: ${intentionalErrors}`);
console.log(`Errors detected: ${errorsDetected}`);
console.log(`Errors missed: ${missedErrors}`);
console.log(`Detection rate: ${detectionRate.toFixed(1)}%`);
console.log('');
console.log(`False positives: ${falsePositives}`);
console.log(`False positive rate: ${falsePositiveRate.toFixed(1)}%`);
console.log('');

// Hypothesis validation
console.log('=== Hypothesis Validation ===');
console.log('HYP-002 Criteria:');
console.log('- Detection rate >= 80%: ' + (detectionRate >= 80 ? '✓ PASS' : '✗ FAIL'));
console.log('- False positive rate < 5%: ' + (falsePositiveRate < 5 ? '✓ PASS' : '✗ FAIL'));
console.log('');

if (detectionRate >= 80 && falsePositiveRate < 5) {
  console.log('✓ HYP-002 CONFIRMED: Line-by-line parser meets validation criteria');
} else {
  console.log('✗ HYP-002 REJECTED: Line-by-line parser does not meet validation criteria');
}

import { validateYAML } from './validator';

// Additional edge case testing for real-world scenarios

const edgeCases = [
  {
    name: 'Real GitHub Actions with complex nesting',
    yaml: `name: Test
on:
  push:
    branches:
      - main
      - develop
  pull_request:
jobs:
  build:
    runs-on: ubuntu-latest
    strategy:
